codeExamples.code:
-- PostgreSQL: see distinct values, correlation, histogram bounds
SELECT attname, n_distinct, null_frac, most_common_vals, histogram_bounds
FROM   pg_stats
WHERE  tablename = ''orders'' AND attname = ''status'';

-- Refresh statistics after a bulk load
ANALYZE orders;

-- Increase histogram resolution for a skewed column
ALTER TABLE orders ALTER COLUMN status SET STATISTICS 500;
ANALYZE orders;

-- SQL Server: view and update
DBCC SHOW_STATISTICS(''dbo.orders'', ''idx_orders_status'');
UPDATE STATISTICS dbo.orders WITH FULLSCAN;

-- Oracle
EXEC DBMS_STATS.GATHER_TABLE_STATS(''SALES'', ''ORDERS'');

-- Correlated columns: city implies state. With independence assumption the
-- optimizer multiplies selectivities and badly under-estimates the result.
SELECT * FROM customers
WHERE  city = ''San Francisco'' AND state = ''CA'';
-- Estimated rows (independence): N * sel(city) * sel(state) -> far too low

-- PostgreSQL: create extended statistics capturing the dependency
CREATE STATISTICS stx_city_state (dependencies, ndistinct)
  ON city, state FROM customers;
ANALYZE customers;
-- Now sel(city AND state) ~= sel(city), since state is functionally implied

-- SQL Server equivalent: multi-column statistics object
CREATE STATISTICS stx_city_state ON dbo.customers(city, state);
